func WithRetry[T any](fn func() (T, error), attempts int) (T, error) {
	var zero T
	var lastErr error
	for i := 0; i < attempts; i++ {
		v, err := fn()
		if err == nil {
			return v, nil
		}
		lastErr = err
		time.Sleep(100 * time.Millisecond) //!issue:1
	}
	return zero, lastErr
}

code.rust:
pub async fn with_retry<T, E, F, Fut>(mut f: F, attempts: u32) -> Result<T, E>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<T, E>>,
{
    let mut last = None;
    for _ in 0..attempts {
        match f().await {
            Ok(v) => return Ok(v),
            Err(e) => last = Some(e),
        }
        tokio::time::sleep(Duration::from_millis(100)).await; //!issue:1
    }
    Err(last.expect("attempts must be > 0"))
}

