public static <T> T withRetry(Callable<T> fn, int attempts) throws Exception {
    Exception last = null;
    for (int i = 0; i < attempts; i++) {
        try {
            return fn.call();
        } catch (Exception e) {
            last = e;
            Thread.sleep(100); //!issue:1
        }
    }
    throw last;
}
